const { spawnSync } = require('child_process');
const BIN = '/workspace/dataset/test4_executable';

function run(valBuf) {
  const arg = Buffer.isBuffer(valBuf) ? valBuf : Buffer.from(String(valBuf), 'utf8');
  const r = spawnSync(BIN, ['--a', arg.toString('latin1')], { encoding: 'buffer' });
  return r;
}

// Better: pass buffer directly via args array requires strings. Use latin1 roundtrip only for
// binary-safe? No -- node encodes argv as UTF-8 from JS string. So build JS string properly.
function runStr(s) {
  const r = spawnSync(BIN, ['--a', s], { encoding: 'buffer' });
  return {
    stdoutHex: r.stdout ? r.stdout.toString('hex') : null,
    stdout: r.stdout ? r.stdout.toString('utf8') : null,
    stderr: r.stderr ? r.stderr.toString('utf8') : null,
    code: r.status,
    signal: r.signal,
    error: r.error ? String(r.error) : null,
  };
}
module.exports = { runStr, run };

const { runStr } = require('/tmp/probe-degenerate/run.js');

const SEPS_PUNCT = [];
for (let c = 33; c < 127; c++) {
  const ch = String.fromCharCode(c);
  if (/[0-9A-Za-z]/.test(ch)) continue;
  SEPS_PUNCT.push(ch);
}
const WS = [' ', '\t', '\n', '\r', '\x0b', '\x0c'];

console.log('=== Q2: each ASCII punct/ws char alone ===');
for (const ch of [...SEPS_PUNCT, ...WS]) {
  const r = runStr(ch);
  console.log(JSON.stringify(ch), 'U+' + ch.charCodeAt(0).toString(16).padStart(4,'0'), '->', r.stdoutHex, 'exit', r.code);
}

