const { spawnSync } = require('child_process');
const BIN='/workspace/dataset/test4_executable';
function eq(s){ // use --a=VALUE form to avoid leading-dash issues
  const r=spawnSync(BIN,['--a='+s],{encoding:'buffer'});
  return {hex:r.stdout?r.stdout.toString('hex'):null,code:r.status,err:r.stderr?r.stderr.toString('utf8').slice(0,120):''};
}
function two(s){
  const r=spawnSync(BIN,['--a',s],{encoding:'buffer'});
  return {hex:r.stdout?r.stdout.toString('hex'):null,code:r.status,err:r.stderr?r.stderr.toString('utf8').slice(0,120):''};
}
console.log('=== Q1 homogeneous "!" repeated ===');
for (const n of [1,2,3,5,17,100,1000]) {
  const s='!'.repeat(n);
  const a=eq(s), b=two(s);
  console.log('n='+n, 'eqform', a.hex, a.code, '| twoarg', b.hex, b.code);
}
console.log('=== Q1 mixed separator strings ===');
const mixes = ['! .,;', '! .,;'.repeat(4), ' \t\n\r\x0b\x0c', '!@#$%^&*()_+={}[]|;:\'",.<>/?`~', ('!@# \t'.repeat(200)), ('~'.repeat(1000)+' '.repeat(1000)), '_', '__', '___', '_'.repeat(50), '.'.repeat(3), '- ', ' -', '-'.repeat(5)];
for (const s of mixes) {
  const a=eq(s);
